<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Dune Line | Overnight Express to Neo-Cairo</title>
  <style>
    :root {
      --bg-dark: #05020A;
      --bg-card: rgba(16, 8, 28, 0.65);
      --sand: #E6B971;
      --sand-dim: #8A6D3B;
      --neon-cyan: #00E5FF;
      --neon-pink: #FF007F;
      --neon-purple: #B026FF;
      --text-main: #F8F8FC;
      --text-muted: #8B8B9E;
      --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
      --container: 1200px;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; }

    body {
      background-color: var(--bg-dark);
      background-image: radial-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px);
      background-size: 40px 40px;
      color: var(--text-main);
      font-family: var(--font-sans);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    /* SVG Noise Overlay */
    body::after {
      content: '';
      position: fixed;
      inset: 0;
      background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
      pointer-events: none;
      z-index: 9999;
      mix-blend-mode: overlay;
    }

    ::selection { background: var(--neon-pink); color: #fff; }
    :focus-visible { outline: 2px solid var(--neon-cyan); outline-offset: 4px; }

    .container {
      max-width: var(--container);
      margin: 0 auto;
      padding: 0 2rem;
      position: relative;
    }

    /* Typography */
    h1, h2, h3, h4 { font-weight: 800; letter-spacing: -0.03em; line-height: 1.1; }
    .text-gradient {
      background: linear-gradient(90deg, var(--sand) 0%, var(--neon-pink) 50%, var(--neon-cyan) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .text-sand { color: var(--sand); }
    .eyebrow {
      font-family: var(--font-mono);
      color: var(--neon-cyan);
      font-size: 0.8rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      display: block;
      margin-bottom: 1rem;
    }

    /* Buttons */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 1rem 2rem;
      border-radius: 4px;
      font-weight: 600;
      font-size: 1rem;
      text-decoration: none;
      transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
      letter-spacing: 0.02em;
      cursor: pointer;
      border: none;
    }
    .btn-primary {
      background: var(--neon-cyan);
      color: #000;
      box-shadow: 0 0 20px rgba(0, 229, 255, 0.3);
    }
    .btn-primary:hover {
      background: #fff;
      box-shadow: 0 0 30px rgba(255, 255, 255, 0.5);
      transform: translateY(-2px);
    }
    .btn-secondary {
      background: rgba(255,255,255,0.02);
      color: #fff;
      border: 1px solid rgba(255,255,255,0.2);
      backdrop-filter: blur(8px);
    }
    .btn-secondary:hover {
      border-color: var(--sand);
      color: var(--sand);
      background: rgba(230, 185, 113, 0.05);
      transform: translateY(-2px);
    }

    /* Navigation */
    nav {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 100;
      padding: 1.5rem 0;
      transition: all 0.4s ease;
      border-bottom: 1px solid transparent;
    }
    nav.scrolled {
      padding: 1rem 0;
      background: rgba(5, 2, 10, 0.85);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }
    .nav-inner { display: flex; align-items: center; justify-content: space-between; }
    .logo {
      display: flex; align-items: center; gap: 0.75rem;
      color: #fff; text-decoration: none;
      font-weight: 800; font-size: 1.25rem; letter-spacing: 0.05em;
    }
    .logo span { font-weight: 300; color: var(--text-muted); }
    .nav-links { display: flex; gap: 2.5rem; }
    .nav-links a {
      color: var(--text-muted); text-decoration: none;
      font-size: 0.9rem; font-weight: 500; transition: color 0.2s;
    }
    .nav-links a:hover { color: var(--neon-cyan); }
    .btn-nav {
      background: transparent; color: #fff;
      border: 1px solid rgba(255,255,255,0.3);
      padding: 0.6rem 1.25rem; border-radius: 4px;
      text-decoration: none; font-size: 0.9rem; font-weight: 600;
      transition: all 0.2s;
    }
    .btn-nav:hover { border-color: var(--neon-cyan); color: var(--neon-cyan); }

    /* Hero */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 8rem 0 4rem;
      overflow: hidden;
    }
    .hero-bg-wrapper {
      position: absolute; inset: 0;
      z-index: 0; pointer-events: none;
      background: var(--bg-dark);
    }
    .hero-scene {
      position: absolute; bottom: 0; left: 0;
      width: 100%; height: 100%;
      will-change: transform;
    }
    .stars-overlay {
      position: absolute; inset: 0;
      background-image: 
        radial-gradient(1px 1px at 15% 25%, #fff, transparent),
        radial-gradient(1.5px 1.5px at 75% 15%, rgba(255,255,255,0.8), transparent),
        radial-gradient(1px 1px at 45% 45%, #fff, transparent),
        radial-gradient(2px 2px at 85% 35%, rgba(0, 229, 255, 0.6), transparent),
        radial-gradient(1px 1px at 25% 65%, #fff, transparent);
      background-size: 300px 300px, 250px 250px, 400px 400px, 350px 350px, 200px 200px;
      animation: twinkle 6s infinite alternate ease-in-out;
      opacity: 0.6;
    }
    @keyframes twinkle { 0% { opacity: 0.3; } 100% { opacity: 0.8; } }

    .hero-content {
      z-index: 10; text-align: center;
      max-width: 900px;
      display: flex; flex-direction: column; align-items: center;
    }
    .hero-content::before {
      content: ''; position: absolute;
      top: 50%; left: 50%; transform: translate(-50%, -50%);
      width: 140%; height: 140%;
      background: radial-gradient(ellipse at center, rgba(5,2,10,0.7) 0%, transparent 60%);
      z-index: -1; pointer-events: none;
    }
    .badge {
      display: inline-flex; align-items: center; gap: 0.5rem;
      font-family: var(--font-mono); font-size: 0.75rem;
      letter-spacing: 0.1em; color: var(--sand);
      border: 1px solid rgba(230, 185, 113, 0.3);
      background: rgba(230, 185, 113, 0.05);
      padding: 0.4rem 1rem; border-radius: 20px;
      margin-bottom: 2rem;
    }
    .badge::before {
      content: ''; width: 6px; height: 6px;
      background: var(--sand); border-radius: 50%;
      box-shadow: 0 0 8px var(--sand);
      animation: pulse 2s infinite;
    }
    .hero h1 {
      font-size: clamp(3.5rem, 7vw, 6rem);
      margin-bottom: 1.5rem;
      text-transform: uppercase;
    }
    .hero p {
      font-size: clamp(1.1rem, 2vw, 1.25rem);
      color: #D0D0E0; max-width: 650px;
      margin: 0 auto 2.5rem; font-weight: 300;
    }
    .hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; justify-content: center; }

    /* Sections Common */
    .section { padding: 8rem 0; position: relative; }
    .section-header { margin-bottom: 4rem; }
    .section-header h2 { font-size: clamp(2.5rem, 4vw, 3.5rem); }
    .section-header.center { text-align: center; }

    /* Features */
    .features-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem;
    }
    .feature-card {
      background: linear-gradient(145deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 16px; padding: 2.5rem;
      transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.3s, box-shadow 0.3s;
    }
    .feature-card:hover {
      transform: translateY(-8px);
      border-color: rgba(0, 229, 255, 0.4);
      box-shadow: 0 15px 40px -15px rgba(0, 229, 255, 0.15);
    }
    .icon-box {
      width: 48px; height: 48px;
      border-radius: 12px;
      background: rgba(0, 229, 255, 0.1);
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 1.5rem; color: var(--neon-cyan);
    }
    .feature-card h3 { font-size: 1.25rem; margin-bottom: 1rem; }
    .feature-card p { color: var(--text-muted); font-size: 0.95rem; }

    /* Timetable */
    .timetable-board {
      background: rgba(10, 5, 20, 0.7);
      border: 1px solid rgba(0, 229, 255, 0.15);
      border-radius: 12px;
      overflow: hidden;
      box-shadow: 0 20px 50px rgba(0,0,0,0.5), inset 0 0 30px rgba(0, 229, 255, 0.03);
      font-family: var(--font-mono);
      backdrop-filter: blur(10px);
    }
    .tt-title-bar {
      display: flex; justify-content: space-between; align-items: center;
      padding: 1rem 1.5rem;
      background: rgba(255,255,255,0.02);
      border-bottom: 1px solid rgba(255,255,255,0.05);
      font-size: 0.8rem; letter-spacing: 0.1em; color: var(--text-muted);
    }
    .live-clock span { color: var(--neon-cyan); }
    .tt-header {
      display: grid; grid-template-columns: 1fr 1fr 1.5fr 1fr;
      padding: 1rem 1.5rem;
      background: rgba(0, 229, 255, 0.03);
      color: var(--neon-cyan); font-size: 0.75rem; letter-spacing: 0.15em;
      border-bottom: 1px solid rgba(0, 229, 255, 0.15);
    }
    .tt-row {
      display: grid; grid-template-columns: 1fr 1fr 1.5fr 1fr;
      padding: 1.25rem 1.5rem;
      border-bottom: 1px solid rgba(255,255,255,0.05);
      align-items: center; transition: background 0.2s;
    }
    .tt-row:last-child { border-bottom: none; }
    .tt-row:hover { background: rgba(0, 229, 255, 0.04); }
    .tt-time { font-size: 1.25rem; color: #fff; font-weight: 600; }
    .tt-time.dim { color: var(--text-muted); font-weight: 400; }
    .tt-vessel { color: #D0D0E0; font-size: 0.9rem; }
    .tt-vessel span {
      color: var(--sand); font-family: var(--font-sans);
      font-style: italic; font-size: 0.85rem; margin-left: 0.75rem; opacity: 0.9;
    }
    .tt-status {
      display: flex; align-items: center; gap: 0.6rem;
      font-size: 0.8rem; color: #4ade80; letter-spacing: 0.05em;
    }
    .tt-row:nth-child(5) .tt-status { color: var(--sand); }
    .dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: currentColor; box-shadow: 0 0 10px currentColor;
      animation: pulse 2s infinite;
    }
    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }

    /* Pricing */
    .pricing-grid {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 2rem; align-items: center;
    }
    .price-card {
      background: var(--bg-card);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 16px; padding: 2.5rem;
      position: relative; backdrop-filter: blur(10px);
    }
    .price-card.popular {
      border: 1px solid var(--neon-pink);
      box-shadow: 0 0 40px rgba(255, 0, 127, 0.12);
      transform: scale(1.05);
      background: linear-gradient(180deg, rgba(255,0,127,0.06), var(--bg-card));
      z-index: 2;
    }
    .popular-badge {
      position: absolute; top: -14px; left: 50%; transform: translateX(-50%);
      background: var(--neon-pink); color: #fff;
      font-family: var(--font-mono); font-size: 0.7rem; font-weight: 700;
      letter-spacing: 0.1em; padding: 5px 14px; border-radius: 20px;
      box-shadow: 0 0 15px rgba(255, 0, 127, 0.5);
      white-space: nowrap;
    }
    .price-card h3 { font-size: 1.5rem; }
    .price-card .desc { color: var(--text-muted); font-size: 0.9rem; margin-top: 0.5rem; }
    .price { font-size: 3rem; font-weight: 800; color: #fff; margin: 1.5rem 0; }
    .price span { font-size: 1rem; color: var(--text-muted); font-weight: 400; font-family: var(--font-sans); }
    .feature-list { list-style: none; margin: 2rem 0; }
    .feature-list li {
      padding: 0.8rem 0; border-bottom: 1px solid rgba(255,255,255,0.05);
      color: #D0D0E0; font-size: 0.9rem; display: flex; align-items: center; gap: 0.75rem;
    }
    .feature-list li:last-child { border-bottom: none; }
    .feature-list li::before { content: '✦'; color: var(--neon-cyan); font-size: 0.8rem; }
    .price-card.popular .feature-list li::before { color: var(--neon-pink); }

    /* Testimonial */
    .testimonial-section { padding: 8rem 0; text-align: center; position: relative; }
    .testimonial-section::before {
      content: ''; position: absolute; top: 0; left: 50%; transform: translateX(-50%);
      width: 1px; height: 80px;
      background: linear-gradient(180deg, transparent, var(--neon-pink));
    }
    .quote-mark {
      font-family: Georgia, serif; font-size: 8rem; line-height: 1;
      color: var(--neon-pink); opacity: 0.15; margin-bottom: -2.5rem;
    }
    blockquote {
      font-size: clamp(1.5rem, 3vw, 2.2rem); font-weight: 300;
      line-height: 1.5; max-width: 850px; margin: 0 auto 3rem; color: #fff;
    }
    .author { display: flex; align-items: center; justify-content: center; gap: 1rem; }
    .avatar {
      width: 48px; height: 48px; border-radius: 50%;
      background: linear-gradient(135deg, var(--sand), var(--neon-pink));
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; color: #000; font-size: 1.1rem;
      box-shadow: 0 0 15px rgba(255, 0, 127, 0.3);
    }
    .author-info { text-align: left; }
    .author-info strong { display: block; font-size: 1rem; }
    .author-info span { font-size: 0.8rem; color: var(--text-muted); font-family: var(--font-mono); letter-spacing: 0.05em; }

    /* Footer */
    footer {
      border-top: 1px solid transparent;
      border-image: linear-gradient(90deg, transparent, var(--sand), var(--neon-pink), var(--neon-cyan), transparent) 1;
      padding: 5rem 0 2rem;
      background: #020105;
      position: relative;
    }
    .footer-grid { display: grid; grid-template-columns: 1fr 2fr; gap: 4rem; margin-bottom: 4rem; }
    .footer-brand p { color: var(--text-muted); font-size: 0.9rem; margin-top: 1rem; max-width: 300px; }
    .footer-links { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
    .link-col h4 { font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.1em; color: #fff; margin-bottom: 1.5rem; }
    .link-col a { display: block; color: var(--text-muted); text-decoration: none; font-size: 0.9rem; margin-bottom: 0.75rem; transition: color 0.2s; }
    .link-col a:hover { color: var(--neon-cyan); }
    .footer-bottom {
      display: flex; justify-content: space-between; align-items: center;
      padding-top: 2rem; border-top: 1px solid rgba(255,255,255,0.05);
      font-family: var(--font-mono); font-size: 0.75rem; color: #55556A;
    }

    /* Reveal Animations */
    .reveal {
      opacity: 0; transform: translateY(30px);
      transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .reveal.visible { opacity: 1; transform: translateY(0); }
    .delay-1 { transition-delay: 0.1s; }
    .delay-2 { transition-delay: 0.2s; }
    .delay-3 { transition-delay: 0.3s; }
    /* Fix for popular card transform conflict with reveal */
    .price-card.popular.reveal { transform: scale(1.05) translateY(30px); }
    .price-card.popular.reveal.visible { transform: scale(1.05) translateY(0); }

    /* Responsive */
    @media (max-width: 960px) {
      .features-grid, .pricing-grid { grid-template-columns: 1fr; max-width: 450px; margin: 0 auto; }
      .price-card.popular { transform: scale(1); }
      .price-card.popular.reveal { transform: translateY(30px); }
      .price-card.popular.reveal.visible { transform: translateY(0); }
      .nav-links { display: none; }
      .footer-grid { grid-template-columns: 1fr; gap: 3rem; }
    }
    @media (max-width: 640px) {
      .tt-header { display: none; }
      .tt-row { grid-template-columns: 1fr 1fr; gap: 1rem; padding: 1.5rem; }
      .tt-vessel { grid-column: 1 / -1; }
      .tt-status { grid-column: 1 / -1; margin-top: 0.5rem; }
      .footer-links { grid-template-columns: 1fr 1fr; }
      .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
      .hero-actions { flex-direction: column; width: 100%; }
      .hero-actions .btn { width: 100%; }
    }
  </style>
</head>
