            <rect x="0" y="750" width="1440" height="28" fill="black"/>
            <rect x="0" y="810" width="1440" height="40" fill="black"/>
          </mask>
        </defs>

        <!-- Sky Base -->
        <rect width="1440" height="900" fill="url(#skyGrad)"/>

        <!-- Static Bright Stars -->
        <g fill="#FFF" opacity="0.7">
          <circle cx="180" cy="120" r="1.5"/><circle cx="420" cy="60" r="1"/>
          <circle cx="850" cy="180" r="2"/><circle cx="1150" cy="90" r="1.5"/>
          <circle cx="1350" cy="220" r="1"/><circle cx="80" cy="320" r="2"/>
