          <circle cx="300" cy="200" r="1"/><circle cx="1050" cy="300" r="1.5"/>
        </g>

        <!-- Neon Sun / Portal (Horizon at y=500) -->
        <circle cx="720" cy="500" r="260" fill="url(#sunGrad)" mask="url(#sunMask)" filter="url(#glow)"/>

        <!-- Horizon Glow Line -->
        <rect x="0" y="498" width="1440" height="4" fill="#00E5FF" filter="url(#glow)"/>

        <!-- Perspective Neon Grid -->
        <g stroke="url(#gridGrad)" stroke-width="1.5">
          <!-- Converging Lines -->
          <line x1="720" y1="500" x2="-300" y2="900"/>
          <line x1="720" y1="500" x2="0" y2="900"/>
